async function getAudio(){if(!audio){const Audio=window.AudioContext||window.webkitAudioContext;if(!Audio)return null;audio=new Audio()}if(audio.state==='suspended')await audio.resume();return audio} function beep(f=440,d=.12){if(muted||volume===0)return;getAudio().then(a=>{if(!a)return;const o=a.createOscillator(),g=a.createGain(),now=a.currentTime;o.type='triangle';o.frequency.setValueAtTime(f,now);g.gain.setValueAtTime(.0001,now);g.gain.exponentialRampToValueAtTime(Math.max(.0002,volume*.2),now+.015);g.gain.exponentialRampToValueAtTime(.0001,now+d);o.connect(g);g.connect(a.destination);o.start(now);o.stop(now+d+.01)}).catch(err=>console.warn('Audio could not start:',err))}
function musicTone(freq,duration,level,type='triangle'){if(!audio||!freq)return;let now=audio.currentTime,o=audio.createOscillator(),g=audio.createGain();o.type=type;o.frequency.setValueAtTime(freq,now);g.gain.setValueAtTime(.0001,now);g.gain.exponentialRampToValueAtTime(Math.max(.0002,volume*level),now+.025);g.gain.exponentialRampToValueAtTime(.0001,now+duration);o.connect(g);g.connect(audio.destination);o.start(now);o.stop(now+duration+.02)}
async function startMusic(){if(!musicOn||musicTimer)return;try{await getAudio();musicStep=0;const melody=[523,659,784,659,587,698,880,698,523,659,784,988,880,784,659,587];musicTimer=setInterval(()=>{if(!audio||audio.state!=='running')return;let i=musicStep%melody.length;musicTone(melody[i],.19,.075,'triangle');if(i%4===0)musicTone([131,147,110,123][Math.floor(i/4)%4],.38,.11,'sine');if(i%2===0)musicTone(melody[i]*2,.08,.025,'sine');musicStep++},230)}catch(err){console.warn('Background music could not start:',err)}}
