function start(){if(!safetyReady()){showActionToast('Complete all safety checks first');return}destination=document.getElementById('destinationSelect').value;helmetStyle=document.getElementById('helmetSelect').value;document.getElementById('destinationHud').textContent=destination;introMode='menu';state='play';time=120;stamina=100;speed=34;danger=0;crashes=0;document.getElementById('crashCount').textContent='CRASHES 0/3';lane=1;lanePos=1;riderDepth=.84;riderDepthTarget=.84;jump=-1;obstacles=[];items=[];popups=[];itemSpawn=1;resetScore();scoreBoard.hidden=false;rushShown=false;announce=null;document.getElementById('timer').parentElement.classList.remove('urgent');spawn=.8;last=performance.now();stage.classList.remove('test-mode','celebrate');overlay.classList.remove('win');testHud.hidden=true;overlay.classList.add('hidden');requestAnimationFrame(loop);if(musicOn)startMusic();beep(550)}
