function input(k){if(state!=='play'&&state!=='test')return;if(k==='left')lane=Math.max(0,lane-1);if(k==='right')lane=Math.min(2,lane+1);if(k==='jump'&&jump<0){jump=0;beep(650)}if(k==='up')riderDepthTarget=Math.max(.62,riderDepthTarget-.12);if(k==='down')riderDepthTarget=Math.min(.84,riderDepthTarget+.12)}
function jumpHeight(){return jump<0?0:Math.sin(Math.min(1,jump/.9)*Math.PI)} let held={};window.addEventListener('keydown',e=>{if(['ArrowLeft','ArrowRight','ArrowUp','ArrowDown',' ','Control'].includes(e.key))e.preventDefault();if(e.key.toLowerCase()==='p'){if(state==='play'||state==='pause')pause();return}if(e.repeat)return;if(e.key==='ArrowLeft')input('left');if(e.key==='ArrowRight')input('right');if(e.key==='ArrowUp')input('up');if(e.key==='ArrowDown')input('down');if(e.code==='Space')input('jump');if(e.key==='Control')held.boost=true});
