const fullscreenBtn=document.getElementById('fullscreenBtn'),snapshotBtn=document.getElementById('snapshotBtn');
function syncFullscreenButton(){let active=document.fullscreenElement===stage||document.webkitFullscreenElement===stage;fullscreenBtn.textContent=active?'EXIT FULL SCREEN':'FULL SCREEN ⛶'}
async function toggleFullscreen(){try{if(document.fullscreenElement===stage||document.webkitFullscreenElement===stage){if(document.exitFullscreen)await document.exitFullscreen();else if(document.webkitExitFullscreen)document.webkitExitFullscreen()}else if(stage.requestFullscreen)await stage.requestFullscreen();else if(stage.webkitRequestFullscreen)stage.webkitRequestFullscreen();else showActionToast('Fullscreen is unavailable in this browser')}catch(e){showActionToast('Could not enter fullscreen')}}
document.addEventListener('fullscreenchange',syncFullscreenButton);document.addEventListener('webkitfullscreenchange',syncFullscreenButton);fullscreenBtn.onclick=toggleFullscreen;
function showActionToast(message){let el=document.getElementById('toast');el.textContent=message;el.classList.add('show');clearTimeout(window.pedalToastTimer);window.pedalToastTimer=setTimeout(()=>el.classList.remove('show'),1500)}
function savePicture(){let filename='pedal-panic-'+new Date().toISOString().replace(/[:.]/g,'-')+'.png';function download(blob){if(!blob){showActionToast('Could not save picture');return}let url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=filename;document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1000);showActionToast('Game picture saved') }try{if(c.toBlob)c.toBlob(download,'image/png');else{let a=document.createElement('a');a.href=c.toDataURL('image/png');a.download=filename;a.click();showActionToast('Game picture saved')}}catch(e){showActionToast('Could not save picture')}}
snapshotBtn.onclick=savePicture;document.getElementById('volume').oninput=e=>{volume=e.target.value/100;document.getElementById('volText').textContent=e.target.value+'%'};document.getElementById('musicOn').onchange=e=>{musicOn=e.target.checked;if(musicOn)startMusic();else stopMusic()};document.getElementById('soundOn').onchange=e=>muted=!e.target.checked;document.getElementById('testSound').onclick=()=>beep(660,.2);
/* ===== Bicycle riding sound effects (synthesized, no external assets) ===== */
let ride=null,tickAcc=0,wasAir=false;
function noiseBuf(a){if(!a._nb){const b=a.createBuffer(1,a.sampleRate*2,a.sampleRate),d=b.getChannelData(0);for(let i=0;i<d.length;i++)d[i]=Math.random()*2-1;a._nb=b}return a._nb}
function ensureRide(){if(ride)return ride;if(!audio||audio.state!=='running')return null;const a=audio,src=a.createBufferSource();src.buffer=noiseBuf(a);src.loop=true;
const tyreF=a.createBiquadFilter();tyreF.type='lowpass';tyreF.frequency.value=380;const tyreG=a.createGain();tyreG.gain.value=0;
const windF=a.createBiquadFilter();windF.type='bandpass';windF.frequency.value=1400;windF.Q.value=.6;const windG=a.createGain();windG.gain.value=0;
src.connect(tyreF);tyreF.connect(tyreG);tyreG.connect(a.destination);src.connect(windF);windF.connect(windG);windG.connect(a.destination);src.start();
ride={tyreF,tyreG,windF,windG};return ride}
function chainTick(vol){const a=audio,now=a.currentTime,s=a.createBufferSource();s.buffer=noiseBuf(a);const f=a.createBiquadFilter();f.type='bandpass';f.frequency.value=2300+Math.random()*900;f.Q.value=3;const g=a.createGain();g.gain.setValueAtTime(vol*(.8+Math.random()*.4),now);g.gain.exponentialRampToValueAtTime(.0001,now+.035);s.connect(f);f.connect(g);g.connect(a.destination);s.start(now,Math.random()*1.5,.05)}
function landThump(vol){const a=audio,now=a.currentTime,o=a.createOscillator(),g=a.createGain();o.type='sine';o.frequency.setValueAtTime(130,now);o.frequency.exponentialRampToValueAtTime(55,now+.14);g.gain.setValueAtTime(Math.max(.0002,vol*.45),now);g.gain.exponentialRampToValueAtTime(.0001,now+.16);o.connect(g);g.connect(a.destination);o.start(now);o.stop(now+.18);chainTick(vol*1.6)}
function rideSound(dt,on){const r=ensureRide();if(!r)return;const a=audio,now=a.currentTime,vol=(muted||!on)?0:volume,air=on&&jump>=0,sp=Math.min(1,speed/64),boost=on&&state==='play'&&held.boost&&stamina>0;
  // Keep a soft, warm tyre-and-chain ambience; wind is intentionally very faint.
  r.tyreG.gain.setTargetAtTime(air?vol*.08:vol*(.22+.28*sp),now,.12);r.tyreF.frequency.setTargetAtTime(180+speed*5,now,.15);
  r.windG.gain.setTargetAtTime(vol*(.001+sp*sp*(boost?.008:.003)),now,.2);r.windF.frequency.setTargetAtTime(700+speed*12+(boost?180:0),now,.2);
  if(vol>0&&!air){tickAcc+=dt*(1.2+speed*.035);let n=0;while(tickAcc>=1&&n++<2){tickAcc-=1;chainTick(vol*.28)}}else tickAcc=Math.min(tickAcc,1);
  if(wasAir&&!air&&on&&vol>0)landThump(vol*.45);wasAir=air}

/* ===== Celebration: destination scenes + fireworks ===== */
const sparks=[],rockets=[];let fwTimer=0,winT=0;
function resetWin(){sparks.length=0;rockets.length=0;fwTimer=0;winT=0}
function fwWhistle(){if(muted||volume===0||!audio||audio.state!=='running')return;const a=audio,now=a.currentTime,o=a.createOscillator(),g=a.createGain();o.type='sine';o.frequency.setValueAtTime(500,now);o.frequency.exponentialRampToValueAtTime(1500,now+.5);g.gain.setValueAtTime(.0001,now);g.gain.exponentialRampToValueAtTime(Math.max(.0002,volume*.05),now+.05);g.gain.exponentialRampToValueAtTime(.0001,now+.5);o.connect(g);g.connect(a.destination);o.start(now);o.stop(now+.52)}
function fwPop(){if(muted||volume===0||!audio||audio.state!=='running')return;const a=audio,now=a.currentTime,n=a.createBufferSource();n.buffer=noiseBuf(a);const f=a.createBiquadFilter();f.type='lowpass';f.frequency.setValueAtTime(2200,now);f.frequency.exponentialRampToValueAtTime(180,now+.4);const g=a.createGain();g.gain.setValueAtTime(Math.max(.0002,volume*1.2),now);g.gain.exponentialRampToValueAtTime(.0001,now+.42);n.connect(f);f.connect(g);g.connect(a.destination);n.start(now,Math.random()*1.4,.45)}
function fwBurst(x,y){const cols=[['#ff4d6d','#ffd166'],['#4dd2ff','#ffffff'],['#7cff6b','#fff27a'],['#ff9f1c','#ff4d6d'],['#c77dff','#ffd6ff'],[palettes[pal].accent,'#ffffff']],cc=cols[Math.floor(Math.random()*cols.length)],n=50+Math.floor(Math.random()*26),ring=Math.random()<.35;for(let i=0;i<n;i++){const a=i/n*Math.PI*2+Math.random()*.08,s=ring?150:50+Math.random()*135;sparks.push({x,y,vx:Math.cos(a)*s,vy:Math.sin(a)*s,life:1,decay:.55+Math.random()*.35,col:cc[i%2],size:2+Math.random()*1.7})}if(sparks.length>900)sparks.splice(0,sparks.length-900);fwPop()}
function updateFireworks(dt){fwTimer-=dt;if(fwTimer<=0){rockets.push({x:Math.random()<.65?(Math.random()<.5?50+Math.random()*170:600+Math.random()*170):90+Math.random()*640,y:310,ty:50+Math.random()*105,vy:-(300+Math.random()*90)});fwTimer=.3+Math.random()*.5;fwWhistle()}
for(let i=rockets.length-1;i>=0;i--){const k=rockets[i];k.y+=k.vy*dt;k.vy*=.992;ctx.strokeStyle='#ffe9a8';ctx.lineWidth=2.2;ctx.beginPath();ctx.moveTo(k.x,k.y);ctx.lineTo(k.x,k.y+15);ctx.stroke();if(k.y<=k.ty||k.vy>-40){fwBurst(k.x,k.y);rockets.splice(i,1)}}
ctx.globalCompositeOperation='lighter';for(let i=sparks.length-1;i>=0;i--){const s=sparks[i];s.vx*=.985;s.vy=s.vy*.985+80*dt;s.x+=s.vx*dt;s.y+=s.vy*dt;s.life-=s.decay*dt;if(s.life<=0){sparks.splice(i,1);continue}ctx.globalAlpha=Math.max(0,s.life);ctx.fillStyle=s.col;ctx.beginPath();ctx.arc(s.x,s.y,s.size*(.5+s.life*.5),0,Math.PI*2);ctx.fill();ctx.globalAlpha=Math.max(0,s.life*.35);ctx.beginPath();ctx.arc(s.x-s.vx*.03,s.y-s.vy*.03,s.size*.9,0,Math.PI*2);ctx.fill()}ctx.globalAlpha=1;ctx.globalCompositeOperation='source-over'}
function disc(x,y,r,c){ctx.fillStyle=c;ctx.beginPath();ctx.arc(x,y,r,0,Math.PI*2);ctx.fill()}
function skyFill(stops,hy){const g=ctx.createLinearGradient(0,0,0,hy);stops.forEach((c,i)=>g.addColorStop(i/(stops.length-1),c));ctx.fillStyle=g;ctx.fillRect(0,0,W,hy+1)}
function starField(t,n,maxY){ctx.fillStyle='#fff';for(let i=0;i<n;i++){ctx.globalAlpha=.25+.55*Math.abs(Math.sin(t*1.4+i*1.7));const s=i%4===0?2.4:1.4;ctx.fillRect((i*149.3)%W,(i*61.7)%maxY,s,s)}ctx.globalAlpha=1}
function glowAt(x,y,r,c){const g=ctx.createRadialGradient(x,y,0,x,y,r);g.addColorStop(0,c+'cc');g.addColorStop(1,c+'00');ctx.fillStyle=g;ctx.fillRect(x-r,y-r,r*2,r*2)}
function ridge(base,amp,f,ph,col){ctx.fillStyle=col;ctx.beginPath();ctx.moveTo(0,H);for(let x=0;x<=W;x+=8)ctx.lineTo(x,base-amp*(Math.sin(x*f+ph)+.5*Math.sin(x*f*2.3+ph*1.7)));ctx.lineTo(W,H);ctx.closePath();ctx.fill()}
