const LB_KEY='pedalPanicLeaderboard.v1',NAME_KEY='pedalPanicPlayerName';let lbMem=[];
function lbLoad(){try{const v=JSON.parse(localStorage.getItem(LB_KEY)||'null');if(Array.isArray(v))return v.filter(e=>e&&Number.isFinite(+e.score)).map(e=>({id:String(e.id),name:String(e.name||'Rider').slice(0,14),icon:String(e.icon||'🚴'),score:Math.round(+e.score),dest:String(e.dest||''),win:!!e.win,t:+e.t||0}))}catch(e){}return lbMem.slice()}
