function playerName(){return (nameInput.value.trim().slice(0,14))||riders[rider][0]}
function saveScore(score,win){const list=lbLoad(),e={id:Date.now().toString(36)+Math.random().toString(36).slice(2,6),name:playerName(),icon:riders[rider][1],score,dest:destination,win,t:Date.now()};list.push(e);list.sort((a,b)=>b.score-a.score||a.t-b.t);lbSave(list.slice(0,50));return{id:e.id,rank:list.findIndex(x=>x.id===e.id)+1,total:list.length,list}}
function renderLb(ol,list,hl,limit){ol.innerHTML='';if(!list.length){const li=document.createElement('li');li.className='empty';li.textContent='No scores yet. Be the first!';ol.appendChild(li);return}
const add=(e,i)=>{const li=document.createElement('li');if(e.id===hl)li.className='me';const rk=document.createElement('span');rk.className='rk';rk.textContent=i<3?['🥇','🥈','🥉'][i]:'#'+(i+1);const nm=document.createElement('span');nm.className='nm';nm.textContent=e.icon+' '+e.name;nm.title=e.dest+(e.win?' · arrived':' · did not finish');const sc=document.createElement('span');sc.className='sc';sc.textContent=e.score.toLocaleString();li.append(rk,nm,sc);ol.appendChild(li)};
list.slice(0,limit).forEach((e,i)=>add(e,i));const idx=list.findIndex(e=>e.id===hl);if(idx>=limit){const g=document.createElement('li');g.className='gap';g.textContent='⋯';ol.appendChild(g);add(list[idx],idx)}}
